/* Microfix 3.8.41: Files gallery + structured file inspector + Code Workspace + browser/snipping polish */
(()=>{
  const BC41={};
  const text=(ru,en)=>state.language==="ru"?ru:en;
  const extOf=obj=>String(obj?.fileName||obj?.name||"").split(".").pop().toLowerCase();
  const structuredExt=new Set(["json","md","markdown","txt","csv","tsv","js","mjs","cjs","ts","tsx","jsx","html","htm","css","scss","sass","less","py","rb","php","java","kt","kts","go","rs","c","h","cpp","cc","cxx","hpp","cs","swift","sh","bash","zsh","ps1","sql","xml","yaml","yml","toml","ini","conf","env","vue","svelte","dart","lua","r","scala","groovy","gradle","dockerfile","graphql","gql"]);
  const archiveExt=new Set(["zip","rar","7z","tar","gz","tgz"]);
  function kindOf(obj){
    const ext=extOf(obj),mime=String(obj?.mime||"").toLowerCase();
    if(obj?.type==="image"||mime.startsWith("image/"))return"image";
    if(mime.startsWith("audio/"))return"audio";
    if(mime.startsWith("video/"))return"video";
    if(mime==="application/pdf"||ext==="pdf")return"pdf";
    if(ext==="json"||mime.includes("json"))return"json";
    if(ext==="md"||ext==="markdown")return"markdown";
    if(ext==="csv"||ext==="tsv"||mime.includes("csv")||mime.includes("spreadsheet")||mime.includes("excel"))return"table";
    if(ext==="zip"||mime.includes("zip"))return"zip";
    if(archiveExt.has(ext)||mime.includes("rar")||mime.includes("7z")||mime.includes("tar")||mime.includes("gzip"))return"archive";
    if(structuredExt.has(ext)||mime.startsWith("text/"))return"code";
    if(/word|officedocument|rtf|opendocument|msword/.test(mime)||["doc","docx","rtf","odt"].includes(ext))return"document";
    return"file";
  }
  function dataBytes(src){
    try{const s=String(src||""),i=s.indexOf(",");if(i<0)return new Uint8Array();const meta=s.slice(0,i),body=s.slice(i+1);if(/;base64/i.test(meta)){const bin=atob(body),out=new Uint8Array(bin.length);for(let j=0;j<bin.length;j++)out[j]=bin.charCodeAt(j);return out}return new TextEncoder().encode(decodeURIComponent(body))}catch{return new Uint8Array()}
  }
  function dataText(src){try{return new TextDecoder("utf-8",{fatal:false}).decode(dataBytes(src))}catch{return""}}
  function setTextData(obj,value){const bytes=new TextEncoder().encode(String(value||""));let bin="";for(let i=0;i<bytes.length;i+=0x8000)bin+=String.fromCharCode(...bytes.subarray(i,i+0x8000));obj.src=`data:${obj.mime||"text/plain"};base64,${btoa(bin)}`;obj.size=bytes.length;queuePersist()}
  function zipEntries(obj){
    const b=dataBytes(obj.src),dv=new DataView(b.buffer,b.byteOffset,b.byteLength),out=[];let p=0;
    while(p+46<=b.length){if(dv.getUint32(p,true)===0x02014b50){const c=dv.getUint32(p+20,true),u=dv.getUint32(p+24,true),nl=dv.getUint16(p+28,true),xl=dv.getUint16(p+30,true),cl=dv.getUint16(p+32,true);const name=new TextDecoder().decode(b.subarray(p+46,p+46+nl));out.push({name,compressed:c,size:u});p+=46+nl+xl+cl;continue}p++}
    return out.slice(0,1000)
  }
  function escLines(s,max=24000){return esc(String(s||"").slice(0,max))}
  function mdOutline(md){const rows=String(md||"").split(/\r?\n/).map((line,i)=>{const m=line.match(/^(#{1,6})\s+(.+)/);return m?{level:m[1].length,title:m[2].trim(),line:i+1}:null}).filter(Boolean);return rows}
  function markdownHtml(md){
    let s=esc(String(md||""));
    s=s.replace(/^######\s+(.+)$/gm,"<h6>$1</h6>").replace(/^#####\s+(.+)$/gm,"<h5>$1</h5>").replace(/^####\s+(.+)$/gm,"<h4>$1</h4>").replace(/^###\s+(.+)$/gm,"<h3>$1</h3>").replace(/^##\s+(.+)$/gm,"<h2>$1</h2>").replace(/^#\s+(.+)$/gm,"<h1>$1</h1>");
    s=s.replace(/```([\s\S]*?)```/g,"<pre><code>$1</code></pre>").replace(/\*\*(.+?)\*\*/g,"<strong>$1</strong>").replace(/\*(.+?)\*/g,"<em>$1</em>").replace(/`([^`]+)`/g,"<code>$1</code>");
    s=s.replace(/^(?:- |\* )(.+)$/gm,"<li>$1</li>").replace(/(?:<li>.*<\/li>\n?)+/g,m=>`<ul>${m}</ul>`);
    return s.split(/\n{2,}/).map(x=>/^<(h\d|ul|pre)/.test(x)?x:`<p>${x.replace(/\n/g,"<br>")}</p>`).join("")
  }
  function tablePreview(textValue,sep){const rows=String(textValue||"").split(/\r?\n/).filter(Boolean).slice(0,18).map(r=>r.split(sep).slice(0,8));return`<div class="bc-table-preview"><table>${rows.map((r,i)=>`<tr>${r.map(c=>`<${i?"td":"th"}>${esc(c)}</${i?"td":"th"}>`).join("")}</tr>`).join("")}</table></div>`}
  function fileIcon(obj){const k=kindOf(obj),label=bcFileShortLabel?.(obj)||extOf(obj).toUpperCase()||"FILE";if(k==="image"&&obj.src)return`<img src="${esc(obj.src)}" alt="">`;return`<span class="bc-gallery-file-icon bc-kind-${k}">${esc(label)}</span>`}

  function renderFilesGallery(){
    const root=document.getElementById("layerList"),search=document.getElementById("layerSearch");if(!root)return;root.classList.add("files-gallery");
    const q=(search?.value||"").trim().toLowerCase(),items=[...objects()].reverse().filter(o=>o.visible!==false&&(o.type==="image"||o.type==="file")&&String(o.name||o.fileName||"").toLowerCase().includes(q));
    root.innerHTML=items.length?items.map(o=>`<button class="bc-file-tile${state.selected.includes(o.id)?" selected":""}" type="button" data-file-id="${o.id}"><span class="bc-file-tile-preview">${fileIcon(o)}</span><span class="bc-file-tile-name">${esc(o.fileName||o.name)}</span></button>`).join(""):`<div class="bc-files-empty">${text("На холсте пока нет файлов и медиа","No files or media on this canvas yet")}</div>`;
    root.querySelectorAll("[data-file-id]").forEach(btn=>{const o=objects().find(x=>x.id===btn.dataset.fileId);btn.addEventListener("click",e=>{if(!o)return;selectObject(o.id,!!(e.ctrlKey||e.metaKey||e.shiftKey),true)});btn.addEventListener("dblclick",()=>o&&(o.type==="image"?focusObject(o):openFileWorkbench(o)))})
  }
  const baseRenderLayers=renderLayers;
  renderLayers=function(){const panel=document.getElementById("layersPanel"),tabs=[...panel?.querySelectorAll(".panel-tabs button")||[]],search=document.getElementById("layerSearch");if(state.ui?.layersTab==="files"){tabs.forEach((b,i)=>b.classList.toggle("active",i===1));if(search)search.placeholder=text("Поиск файлов","Search files");renderFilesGallery();return}document.getElementById("layerList")?.classList.remove("files-gallery");tabs.forEach((b,i)=>b.classList.toggle("active",i===0));if(search)search.placeholder=tr("searchLayers");baseRenderLayers()};
  const panel=document.getElementById("layersPanel"),tabs=[...panel?.querySelectorAll(".panel-tabs button")||[]];
  tabs[0]?.addEventListener("click",()=>{state.ui.layersTab="layers";queuePersist();renderLayers()});tabs[1]?.addEventListener("click",()=>{state.ui.layersTab="files";queuePersist();renderLayers()});
  document.getElementById("layerSearch")?.addEventListener("input",()=>{if(state.ui?.layersTab==="files")renderFilesGallery()});

  function fileInspectorHTML(obj){
    const k=kindOf(obj),name=esc(obj.fileName||obj.name),raw=dataText(obj.src);let body="";
    if(k==="json"){let v=raw;try{v=JSON.stringify(JSON.parse(raw),null,2)}catch{}body=`<pre class="bc-file-code"><code>${escLines(v)}</code></pre>`}
    else if(k==="markdown"){const outline=mdOutline(raw);body=`<div class="bc-md-outline">${outline.length?outline.map(h=>`<div style="--level:${h.level}"><b>${esc(h.title)}</b><small>${h.line}</small></div>`).join(""):`<span>${text("Заголовков не найдено","No headings found")}</span>`}</div>`}
    else if(k==="table")body=tablePreview(raw,extOf(obj)==="tsv"?"\t":",");
    else if(k==="zip"){const entries=zipEntries(obj);body=`<div class="bc-archive-list">${entries.length?entries.map(e=>`<div><span>${esc(e.name)}</span><small>${formatBytes(e.size)}</small></div>`).join(""):`<span>${text("Не удалось прочитать список файлов архива","Could not read archive file list")}</span>`}</div>`}
    else if(k==="code")body=`<pre class="bc-file-code"><code>${escLines(raw)}</code></pre>`;
    else if(k==="pdf")body=`<div class="bc-file-inspector-hero"><span class="bc-gallery-file-icon bc-kind-pdf">PDF</span><strong>${name}</strong></div>`;
    else if(k==="archive")body=`<div class="bc-file-inspector-hero"><span class="bc-gallery-file-icon bc-kind-archive">${esc(bcFileShortLabel?.(obj)||"ARC")}</span><strong>${name}</strong><small>${text("ZIP показывает состав архива; остальные форматы открываются как файл.","ZIP shows archive contents; other archive formats open as files.")}</small></div>`;
    else body=`<div class="bc-file-inspector-hero"><span class="bc-gallery-file-icon bc-kind-${k}">${esc(bcFileShortLabel?.(obj)||"FILE")}</span><strong>${name}</strong></div>`;
    return `<div class="section-title">${text("СОДЕРЖИМОЕ","CONTENTS")}</div>${body}<div class="bc-file-actions"><button class="primary-btn" data-file-workbench>${text("Открыть в окне","Open in window")}</button><button class="soft-btn" data-action="duplicate">${tr("duplicate")}</button><button class="soft-btn danger" data-action="delete">${tr("delete")}</button></div>`
  }
  const baseRenderInspector=renderInspector;
  renderInspector=function(){const picked=selectedObjects();if(picked.length===1&&picked[0].type==="file"){cleanupSmartSelects();const obj=picked[0],root=document.getElementById("inspectorBody"),title=document.getElementById("inspectorTitle");renderColorBar();if(title)title.textContent=obj.fileName||obj.name;if(root){root.innerHTML=fileInspectorHTML(obj);root.querySelector("[data-file-workbench]")?.addEventListener("click",()=>openFileWorkbench(obj));root.querySelector('[data-action="duplicate"]')?.addEventListener("click",duplicateSelection);root.querySelector('[data-action="delete"]')?.addEventListener("click",deleteSelection)}return}baseRenderInspector()};

  let workbench=null,workTabs=[];
  function workbenchBody(obj){const k=kindOf(obj),raw=dataText(obj.src);if(k==="pdf")return`<iframe class="bc-workbench-pdf" src="${obj.src}#toolbar=1&navpanes=1"></iframe>`;if(k==="markdown")return`<div class="bc-workbench-split"><textarea data-file-edit>${esc(raw)}</textarea><article class="bc-markdown-preview">${markdownHtml(raw)}</article></div>`;if(k==="json"||k==="code")return`<div class="bc-workbench-split bc-code-workbench"><textarea data-file-edit spellcheck="false">${esc(raw)}</textarea><pre><code>${escLines(k==="json"?(()=>{try{return JSON.stringify(JSON.parse(raw),null,2)}catch{return raw}})():raw)}</code></pre></div>`;if(k==="table")return`<div class="bc-workbench-table">${tablePreview(raw,extOf(obj)==="tsv"?"\t":",")}</div>`;if(k==="zip")return`<div class="bc-workbench-archive">${zipEntries(obj).map(e=>`<div><span>${esc(e.name)}</span><small>${formatBytes(e.size)}</small></div>`).join("")}</div>`;return`<div class="bc-workbench-generic">${fileIcon(obj)}<strong>${esc(obj.fileName||obj.name)}</strong><small>${esc(obj.mime||"")}</small></div>`}
  function renderWorkbench(){if(!workbench)return;const active=workTabs.find(t=>t.active)||workTabs[0];if(!active){workbench.remove();workbench=null;return}workTabs.forEach(t=>t.active=t===active);workbench.querySelector(".bc-workbench-tabs").innerHTML=workTabs.map(t=>`<button class="${t.active?"active":""}" data-work-tab="${t.obj.id}">${esc(t.obj.fileName||t.obj.name)}<i data-work-close="${t.obj.id}">×</i></button>`).join("");workbench.querySelector(".bc-workbench-body").innerHTML=workbenchBody(active.obj);workbench.querySelectorAll("[data-work-tab]").forEach(b=>b.addEventListener("click",e=>{if(e.target.closest("[data-work-close]"))return;workTabs.forEach(t=>t.active=t.obj.id===b.dataset.workTab);renderWorkbench()}));workbench.querySelectorAll("[data-work-close]").forEach(x=>x.addEventListener("click",e=>{e.stopPropagation();workTabs=workTabs.filter(t=>t.obj.id!==x.dataset.workClose);if(workTabs.length&&!workTabs.some(t=>t.active))workTabs[0].active=true;renderWorkbench()}));const edit=workbench.querySelector("[data-file-edit]");if(edit)edit.addEventListener("input",()=>{setTextData(active.obj,edit.value);if(kindOf(active.obj)==="markdown"){const p=workbench.querySelector(".bc-markdown-preview");if(p)p.innerHTML=markdownHtml(edit.value)}else{const pre=workbench.querySelector("pre code");if(pre)pre.textContent=kindOf(active.obj)==="json"?(()=>{try{return JSON.stringify(JSON.parse(edit.value),null,2)}catch{return edit.value}})():edit.value}})}
  function openFileWorkbench(obj){if(!workbench){workbench=document.createElement("section");workbench.className="bc-file-workbench";workbench.innerHTML=`<header><div class="bc-workbench-tabs"></div><button type="button" class="bc-workbench-close">×</button></header><div class="bc-workbench-body"></div>`;document.body.append(workbench);workbench.querySelector(".bc-workbench-close").addEventListener("click",()=>{workbench.remove();workbench=null;workTabs=[]})}let tab=workTabs.find(t=>t.obj.id===obj.id);if(!tab){tab={obj,active:true};workTabs.push(tab)}workTabs.forEach(t=>t.active=t===tab);renderWorkbench()}
  globalThis.BriefCraftOpenFileWorkbench=openFileWorkbench;

  function inferLang(name){const e=String(name||"").split(".").pop().toLowerCase();return ({html:"html",htm:"html",md:"markdown",markdown:"markdown",json:"json",css:"css",scss:"scss",js:"javascript",mjs:"javascript",cjs:"javascript",ts:"typescript",tsx:"typescript",jsx:"javascript",py:"python",rb:"ruby",php:"php",java:"java",go:"go",rs:"rust",c:"c",cpp:"cpp",cc:"cpp",cs:"csharp",swift:"swift",sh:"shell",bash:"shell",sql:"sql",xml:"xml",yaml:"yaml",yml:"yaml",toml:"toml",csv:"csv",svg:"svg"})[e]||"text"}
  function ensureCodeFiles(obj){if(!Array.isArray(obj.codeFiles)||!obj.codeFiles.length){const name=obj.codeFileName||"index.html";obj.codeFiles=[{id:uid("codefile"),name,language:inferLang(name),content:String(obj.code||"")}];obj.activeCodeFile=obj.codeFiles[0].id}if(!obj.codeFiles.some(f=>f.id===obj.activeCodeFile))obj.activeCodeFile=obj.codeFiles[0].id;return obj.codeFiles}
  function activeCodeFile(obj){return ensureCodeFiles(obj).find(f=>f.id===obj.activeCodeFile)||obj.codeFiles[0]}
  function codePreview(obj){const f=activeCodeFile(obj),files=ensureCodeFiles(obj);if(f.language==="html"){let html=f.content;const css=files.filter(x=>["css","scss"].includes(x.language)).map(x=>x.content).join("\n"),js=files.filter(x=>["javascript","typescript"].includes(x.language)).map(x=>x.content).join("\n");if(css)html=html.replace(/<\/head>/i,`<style>${css}</style></head>`);if(js)html=html.replace(/<\/body>/i,`<script>${js.replace(/<\/script>/gi,"<\\/script>")}<\/script></body>`);return resolveBriefCraftAssetUris(html)}if(f.language==="markdown")return`<!doctype html><meta charset="utf-8"><style>body{font:15px/1.6 system-ui;padding:28px;color:#1b2230}pre{background:#111827;color:#e7efff;padding:16px;border-radius:10px;overflow:auto}code{font-family:ui-monospace,monospace}</style>${markdownHtml(f.content)}`;if(f.language==="svg")return`<!doctype html><style>body{margin:0;display:grid;place-items:center;min-height:100vh;background:white}svg{max-width:95%;max-height:95vh}</style>${f.content}`;if(f.language==="json"){let v=f.content;try{v=JSON.stringify(JSON.parse(v),null,2)}catch{}return`<!doctype html><style>body{margin:0;background:#0d1118;color:#dce7ff}pre{white-space:pre-wrap;padding:24px;font:13px/1.55 ui-monospace,monospace}</style><pre>${esc(v)}</pre>`}if(f.language==="csv")return`<!doctype html><style>body{font:13px system-ui;padding:20px}table{border-collapse:collapse}td,th{border:1px solid #d9dde7;padding:6px 8px}</style>${tablePreview(f.content,",")}`;return`<!doctype html><style>body{margin:0;background:#0d1118;color:#dce7ff}pre{white-space:pre-wrap;padding:24px;font:13px/1.55 ui-monospace,monospace}</style><pre>${esc(f.content)}</pre>`}
  function codeWorkspaceHTML(obj){const files=ensureCodeFiles(obj),active=activeCodeFile(obj);return `${objectBar(obj,`<button class="code-view-toggle" type="button">${obj.codeViewMode==="preview"?text("Код + preview","Code + preview"):text("Только preview","Preview only")}</button><button class="code-run">${tr("run")}</button>`)}<div class="bc-code-tabs">${files.map(f=>`<button class="${f.id===obj.activeCodeFile?"active":""}" data-code-tab="${f.id}"><span>${esc(f.name)}</span>${files.length>1?`<i data-code-tab-close="${f.id}">×</i>`:""}</button>`).join("")}<button class="bc-code-add" type="button" title="${text("Новый файл","New file")}">+</button></div><div class="object-content code-layout ${obj.codeViewMode==="preview"?"preview-only":""}" style="--code-split:${Math.max(18,Math.min(82,Number(obj.codeSplit)||50))}%"><textarea spellcheck="false" data-code-language="${esc(active.language)}">${esc(active.content)}</textarea><div class="code-splitter" title="${text("Потяни границу","Drag divider")}"></div><iframe sandbox="allow-scripts"></iframe></div>`}
  const baseObjectHTML=objectHTML,baseBindCode=bindCode;
  objectHTML=function(obj){if(obj.type==="code")return codeWorkspaceHTML(obj);if(obj.type==="browser")return `${objectBar(obj)}<div class="object-content bc-browser-shell"><div class="browser-chrome bc-browser-chrome"><input class="browser-url" value="${esc(obj.url||"")}" placeholder="https://"><div><button class="browser-interact ${obj.browserInteract?"active":""}" title="${obj.browserInteract?text("Вернуть управление холсту","Return canvas control"):text("Работать внутри страницы","Interact with page")}">${obj.browserInteract?text("Холст","Canvas"):text("Работать","Interact")}</button><button class="browser-go">${tr("go")}</button><button class="browser-design" title="${tr("editLayout")}">${svgIcon("i-design")}</button><button class="browser-code" title="${tr("viewCode")}">${svgIcon("i-codeview")}</button><button class="browser-open" title="${tr("openTab")}">↗</button></div></div><div class="browser-view ${obj.browserInteract?"interacting":"canvas-locked"}"><div class="browser-empty"><div class="browser-empty-card bc-browser-empty"><b>${text("Живая ссылка рядом с проектом","A live reference beside your project")}</b><span>${text("Открывайте сайты, референсы и AI-сервисы прямо на общей карте. Совместимые страницы живут здесь, защищённые сервисы открываются во вкладке и остаются связанными с проектом.","Keep websites, references and AI services on the same project map. Compatible pages live here; protected services open in a tab and stay linked to the project.")}</span><div class="ai-shortcuts"><button data-chat-url="https://chatgpt.com/">ChatGPT</button><button data-chat-url="https://claude.ai/">Claude</button><button data-chat-url="https://gemini.google.com/">Gemini</button></div>${obj.url?`<div class="browser-status"><i></i>${tr("linked")}</div>`:""}</div></div><iframe sandbox="allow-same-origin" hidden></iframe><div class="browser-input-shield" title="${text("Колесо управляет холстом. Нажмите «Работать», чтобы взаимодействовать со страницей.","Wheel controls the canvas. Click Interact to use the page.")}"></div><div class="browser-edit-note" hidden>${tr("snapshotReady")}</div></div></div>`;return baseObjectHTML(obj)};
